from math import exp, log, sqrt

def smile_iv(coeffs, m):
    """Level 3's fitted smile at standardised moneyness m."""
    a, b, c = coeffs
    return a + b * m + c * m * m

def node_iv(surface, K, T, F_of_T):
    """Implied vol at strike K on the expiry node T."""
    return smile_iv(surface[T], log(K / F_of_T(T)) / sqrt(T))

