widget.solution:
def calendar_violations(surface, F_of_T, ks):
    """(k, T1, T2) where total variance falls between expiries."""
    Ts = sorted(surface)
    out = []
    for k in ks:
        w = []
        for T in Ts:
            K = F_of_T(T) * exp(k)         # same k, a new strike
            w.append(node_iv(surface, K, T, F_of_T) ** 2 * T)
        for i in range(len(Ts) - 1):
            if w[i + 1] < w[i]:
                out.append((k, Ts[i], Ts[i + 1]))
    return out
